style.css:
/* Void Search — Google */

:root {
  /* swap these colours if you like */
  --my-outline: #24132f;
  --my-glow: #713c91;
  --my-text: #ffffff;
}

/* transparent search bar */
textarea,
input[type="text"] {
  background: transparent !important;
  color: var(--my-text) !important;
  border: 2px solid var(--my-outline) !important;
  border-radius: 30px !important;
  box-shadow: 0 0 8px var(--my-glow) !important;
  backdrop-filter: blur(10px) !important;
}

/* purple-black outline on hover */
textarea:hover,
input[type="text"]:hover,
textarea:focus,
input[type="text"]:focus {
  border-color: var(--my-glow) !important;
  box-shadow: 0 0 14px var(--my-glow) !important;
  outline: none !important;
}
